mapper.select:
SELECT r.id, r.refund_no AS refundNo, r.payment_order_id AS paymentOrderId, p.order_no AS paymentOrderNo, r.subscription_id AS subscriptionId, r.user_id AS userId, r.refund_amount AS refundAmount, r.refund_reason AS refundReason, r.provider, r.provider_refund_no AS providerRefundNo, r.provider_status AS providerStatus, r.status, r.review_by AS reviewBy, r.review_time AS reviewTime, r.review_remark AS reviewRemark, r.requested_time AS requestedTime, r.completed_time AS completedTime, r.failure_reason AS failureReason FROM ai_refund_order r INNER JOIN ai_payment_order p ON p.id = r.payment_order_id
r.user_id = #{userId}
AND r.status = #{status}
AND ( r.refund_no LIKE CONCAT('%', #{keyword}, '%') OR p.order_no LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY r.create_time DESC
